\mathcal{E} = -\frac{d\varphi}{dt} = -\frac{d}{dt}(4t^2 + 2t - 10) = -8t - 2
\end{equation}

\begin{equation}
t = 2 \text{ s এ আবিষ্ট তড়িচ্ছালক বল, } \mathcal{E} = -8(2) - 2 = -18 \text{ V}
\end{equation}

\begin{equation}
\therefore \text{ তড়িৎপ্রবাহের মান } = 18 \text{ V [খণ্ড চিহ্ন আগাহু করে]}
\end{equation}

