\section{পদার্থবিজ্ঞান ছত্তীয় পত্র}
\subsection{৫.৭.৩ স্বক্ষীয় আবেশ গুণাঙ্ক নির্ণয় (The Determination of Self Inductance)}

ধরা যাক, একটি কুণ্ডলীর মধ্য দিয়ে গমনকারী চৌম্বক ফ্লাক্স $\Phi_{B}$। কুণ্ডলীর পাক সংখ্যা $N$ হলে ফ্যারাডের তাড়িতচৌম্বক আবেশের সূত্রানুসারে কুণ্ডলীতে আবিষ্কৃত তড়িচ্ছালক বল,

\begin{equation}
\mathcal{E} = -N \frac{d\Phi_{B}}{dt}
\end{equation}

আবার, স্বক্ষীয় আবেশের ক্ষেত্রে,

\begin{equation}
\mathcal{E} = -L \frac{di}{dt}
\end{equation}

সুতরাং, $L \frac{di}{dt} = N \frac{d\Phi_{B}}{dt}$

সময়ের সাপেক্ষে সমাকলন করে পাই,

\begin{equation}
Li = N\Phi_{B}
\end{equation}

\begin{equation}
\therefore L = \frac{N\Phi_{B}}{i}
\end{equation}

(৫.১০) নং সমীকরণটি ফ্যারাডের সূত্রে ওপর ভিত্তি করে প্রতিষ্ঠিত। এ সমীকরণের সাহায্যে সরাসরি কুণ্ডলীর পাক সংখ্যা ও তড়িৎ প্রবাহের ফলে কুণ্ডলীতে উৎপন্ন চৌম্বক ফ্লাক্স থেকে স্বক্ষীয় আবেশ গুণাঙ্ক নির্ণয় করা যায়। কুণ্ডলীতে উৎপন্ন চৌম্বক ফ্লাক্স এর মধ্য দিয়ে তড়িৎ প্রবাহের সমানুপাতিক বলে স্বক্ষীয় আবেশ গুণাঙ্ক তড়িৎ প্রবাহের ওপর নির্ভর করে না।

\section*{গাণিতিক উদাহরণ}

\textbf{উদাহরণ-৫.৬:} 400 পাকবিশিষ্ট একটি কুণ্ডলীর মধ্য দিয়ে 2 A বিদ্যুৎ প্রবাহকালে 4×10\textsuperscript{-4} Wb চৌম্বক ফ্লাক্স উৎপন্ন হয়। কুণ্ডলীর স্বক্ষীয় আবেশ গুণাঙ্ক নির্ণয় করো।

আমরা জানি, কুণ্ডলীর স্বক্ষীয় আবেশ গুণাঙ্ক,

\begin{equation}
L = \frac{N\Phi_{B}}{i}
\end{equation}

\begin{equation}
= \frac{(400)(4 \times 10^{-4} \text{ Wb})}{2 \text{ A}}
\end{equation}

\begin{equation}
= 8 \times 10^{-2} \text{ H}
\end{equation}

\textbf{উদাহরণ-৫.৭:} 120 V এর একটি ব্যাটারির সাথে 5 Ω রোধের একটি তার কুণ্ডলী যুক্ত আছে। বুননীর স্থির প্রবাহমাত্রা 20 A থেকে শূন্য নামতে 0.04 s সময় লাগে। কুণ্ডলীর স্বক্ষীয় আবেশ গুণাঙ্ক নির্ণয় করো।

ধরি, কুণ্ডলীতে আবিষ্কৃত তড়িচ্ছালক শক্তি, $\mathcal{E}'$

আমরা জানি, আর্মেচার কুণ্ডলীর প্রবাহমাত্রা,

\begin{equation}
I = \frac{\mathcal{E} - \mathcal{E}'}{R}
\end{equation}

বা, $\mathcal{E}' = \mathcal{E} - IR = 120 - (20 \times 5) = 20 \text{ V}$

আবার,

\begin{equation}
\text{স্বক্ষীয় আবেশ গুণাঙ্ক}, L = \frac{\mathcal{E}'}{\frac{dI}{dt}} = \frac{\mathcal{E}'dt}{dt}
\end{equation}

\begin{equation}
\therefore L = \frac{20 \times 0.04}{20} = 0.04 \text{ H}
\end{equation}

