\begin{equation}
\therefore \overline{E} = \frac{1}{T} \int_{0}^{T} E_m \sin \omega t \, dt
\end{equation}
\begin{equation}
= -\frac{E_m}{\omega T} \left[ \cos \omega t \right]_{0}^{T}
\end{equation}
\begin{equation}
= -\frac{E_m}{\omega T} \left[ \cos \omega T - \cos 0 \right]
\end{equation}

