\subsection*{পাঠ 10}
\textbf{দিক পরিবর্তী তড়িচ্চালক বল ও প্রবাহের বর্গমূলীয় গড় মান}

\subsubsection*{৫.১৩ দিক পরিবর্তী তড়িচ্চালক বল ও প্রবাহের বর্গমূলীয় গড় মান বা মূল গড় বর্গ মান}
\textbf{Root Mean Square Value of Alternating EMF and Current}

আমরা জানি, পূর্ণ চক্রের জন্য দিকপরিবর্তী তড়িচ্চালক বল বা প্রবাহের গড় মান শূন্য কারণ পূর্ণ চক্রের অর্ধেকের জন্য এদের মান ধনাত্মক এবং বাকি অর্ধেকের জন্য ঋণাত্মক। কিন্তু $e^2$ বা $i^2$ ধনাত্মক হওয়ায় পূর্ণ চক্রে এদের গড় মান শূন্য নয়।

\subsubsection*{৫.১৩.১ তড়িচ্চালক বল ও প্রবাহের বর্গমূলীয় গড় মান বা মূল গড় বর্গ মান ও শীর্ষমান (Root Mean Square and Peak Value of Electromotive Force and Current)}

কোনো সময়ের তাংক্ষণিক তড়িচ্চালক বলের বর্গকে সময়ের সাপেক্ষে নিদিষ্ট সময়সীমার মধ্যে সমাকলন করে উত্ত সময় দ্বারা ভাগ করলে ঐ সময়সীমার গড় বর্গ তড়িচ্চালক বল পাওয়া যায়। সুতরাং একটি পূর্ণ চক্রের জন্য গড় বর্গ তড়িচ্চালক বল-
\begin{equation}
\overline{\varepsilon^2} = \frac{1}{T} \int_{0}^{T} \varepsilon^2 dt
\end{equation}
এখানে, $T=$ দিক পরিবর্তী তড়িচ্চালক বলের পর্যায়কাল। কিন্তু দিক পরিবর্তী তড়িচ্চালক বলকে লেখা যায়-
\begin{equation}
\varepsilon = \varepsilon_m \sin \omega t
\end{equation}
এখানে, $\varepsilon_m=$ তড়িচ্চালক বলের সর্বোচ্চ মান এবং $\omega=$ তড়িচ্চালক বলের কৌণিক কম্পাক্ষ। সুতরাং
\begin{equation}
\overline{\varepsilon^2} = \frac{1}{T} \int_{0}^{T} \varepsilon_m^2 \sin^2 \omega t dt = \frac{\varepsilon_m^2}{T} \int_{0}^{T} \sin^2 \omega t dt
\end{equation}

\end{document}

---

\begin{equation}
\mathcal{E} = \mathcal{E}_m \sin \omega t
\end{equation}
এখানে, \(\mathcal{E}_m\) = তড়িৎচালক বলের সর্বোচ্চ মান এবং \(\omega\) = তড়িৎচালক বলের কৌণিক কম্পাঙ্ক। সূত্রাং:

\begin{equation}
\overline{\mathcal{E}^2} = \frac{1}{T} \int_0^T \mathcal{E}_m^2 \sin^2 \omega t \, dt = \frac{\mathcal{E}_m^2}{T} \int_0^T \sin^2 \omega t \, dt
\end{equation}

\begin{equation}
= \frac{\mathcal{E}_m^2}{2T} \int_0^T (1 - \cos 2\omega t) \, dt = \frac{\mathcal{E}_m^2}{2T} \left( [t]_0^T - \frac{1}{2\omega} [\sin 2\omega t]_0^T \right)
\end{equation}

\begin{equation}
= \frac{\mathcal{E}_m^2}{2T} \left( [T - 0] - \frac{1}{2\omega} [\sin 2\omega T - \sin 0] \right)
\end{equation}

\begin{equation}
= \frac{\mathcal{E}_m^2}{2T} T \quad \text{[যেহেতু \(\omega = \frac{2\pi}{T}\) বা, \(\omega T = 2\pi\)]}
\end{equation}

\begin{equation}
= \frac{\mathcal{E}_m^2}{2}
\end{equation}

সূত্রাং দিক পরিবর্তী তড়িৎচালক বলের মূল গড় বর্গ মান:

\begin{equation}
\mathcal{E}_{rms} = \sqrt{\overline{\mathcal{E}^2}} = \sqrt{\frac{\mathcal{E}_m^2}{2}} = \frac{\mathcal{E}_m}{\sqrt{2}} = 0.707 \mathcal{E}_m
\end{equation}

অর্থাৎ, দিক পরিবর্তী তড়িৎচালক বলের মূল গড় বর্গ মান এর শীর্ষমানের \(\frac{1}{\sqrt{2}}\) বা 0.707 গুণ বা 70.7%।

অনুরূপভাবে, দিক পরিবর্তী তড়িৎ প্রবাহের মূল গড় বর্গ মান,

\begin{equation}
i_{rms} = \sqrt{\overline{i^2}} = \sqrt{\frac{i_m^2}{2}} = \frac{i_m}{\sqrt{2}} = 0.707 i_m
\end{equation}

অর্থাৎ, দিক পরিবর্তী তড়িৎ প্রবাহের মূল গড় বর্গ মান এর শীর্ষমানের \(\frac{1}{\sqrt{2}}\) বা 0.707 গুণ বা 70.7%।

\begin{equation}
\text{বাড়ির কাজ} \\
\text{কোনো দিক পরিবর্তী উৎসের তড়িৎচালক বলের সমীকরণ: } \mathcal{E} = 10 \sin (50 \pi) + 5 \sin (100 \pi) \text{ হলে এর মূল গড় বর্গ মান কত? }
