\tag{5.30}
\end{equation}

\textbf{গাণিতিক উদাহরণ}

\textbf{উদাহরণ-5.13:} একটি এ. সি. উৎসের বিষ্টার 160 V এবং কম্পাঙ্ক 60 Hz। এ উৎসের সাথে 20 Ω রোধ যুক্ত করা হলে কার্যকর ভোল্টেজ, কার্যকর প্রবাহমাত্রা এবং উত্তাপজনিত শক্তিক্ষয় নির্ণয় করো।

\textbf{দিকপরিবর্তিত প্রবাহের ফেরে আমরা জানি, কার্যকর ভোল্টেজ হচ্ছে বিভবের মূল গড় বর্গ মান। অর্থাৎ}

\begin{equation}
\mathcal{E}_{eff} = \mathcal{E}_{rms} = 0.707 \mathcal{E}_{m}
\end{equation}
\begin{equation}
= 0.707 \times 160 V
\end{equation}
\begin{equation}
= 113.12 V
\end{equation}

\textbf{কার্যকর প্রবাহ,}

\begin{equation}
i_{eff} = \frac{\mathcal{E}_{eff}}{R} = \frac{113.12 V}{20 \Omega} = 5.656 A
\end{equation}

এবং উত্তাপজনিত শক্তি ক্ষয়ের হার,

\begin{equation}
P = i_{eff}^2 R = (5.656 A)^2 \times 20 \Omega = 639.8 J \cdot s^{-1}
\end{equation}

\textbf{উদাহরণ-5.18:} একটি আরেকটি ট্রান্সফর্মার 200 V সরবরাহ করে 2000 V পাওয়া যায়। ট্রান্সফর্মারটির মুখ্য কুণ্ডলীর পাক সংখ্যা 300 এবং রোধ 0.5 Ω হলে গোল কুণ্ডলীর পাকসংখ্যা ও রোধ নির্ণয় করো।

\textbf{ট্রান্সফর্মারের ফেরে আমরা জানি,}

\begin{equation}
\frac{\mathcal{E}_P}{\mathcal{E}_S} = \frac{N_P}{N_S}
\end{equation}
\begin{equation}
\therefore N_S = N_P \times \frac{\mathcal{E}_S}{\mathcal{E}_P} = 300 \times \frac{2000 V}{200 V} = 3000
\end{equation}

\textbf{আবার,}

\begin{equation}
\frac{\mathcal{E}_P^2}{\mathcal{E}_S^2} = \frac{R_P}{R_S}
\end{equation}
\begin{equation}
\therefore R_S = \frac{\mathcal{E}_S^2 R_P}{\mathcal{E}_P^2} = \frac{(2000 V)^2 (0.5 \Omega)}{(200 V)^2} = 50 \Omega
\end{equation}

