\section{তড়িতচৌম্বকীয় আবেশ ও পরিবর্তী প্রভাব}

\subsection{উদাহরণ-২}
শিলা দিকপরবর্তী তড়িচ্ছালক শক্তির একটি সমীকরণ লিখল এভাবে $E = 6\sin 314t$. নাভিল বলল, কার্যকর তড়িচ্ছালক শক্তির মান 6 V এর কম হবে।

\subsubsection{ক. তড়িচ্ছালক বলের পর্যায়কাল নির্ণয় করো।}
\subsubsection{খ. নাভিল কি সঠিক বলেছিল? সেটা মূল নিয়মে কার্যকর তড়িচ্ছালক শক্তি নির্ণয়পূর্বক যাচাই করো।}

\subsubsection{ক. এখানে, $E = 6\sin 314t$}
একে $E = E_m\sin \omega t$ এর সাথে তুলনা করে পাই,
\begin{equation}
\omega = 314
\end{equation}
বা, $\frac{2\pi}{T} = 314$
\begin{equation}
\therefore T = \frac{2\pi}{314} = 0.02 \text{ sec}
\end{equation}

\subsubsection{খ. তড়িচ্ছালক বলের সমীকরণ, $E = 6\sin 314t$}
কোনো সময়ের তাত্ক্ষণিক তড়িচ্ছালক বলের বর্গকে সময়ের সাপেক্ষে নির্দিষ্ট সময়সীমার মধ্যে সমাকলন করে উত্ত সময় দ্বারা ভাগ করলে ঐ সময়সীমার গড় বর্গ তড়িচ্ছালক বল পাওয়া যায়। সুতরাং একটি পূর্ণ চক্রের জন্য গড় তড়িচ্ছালক বল-
\begin{equation}
\overline{E}^2 = \frac{1}{T}\int_{0}^{T} E^2 dt
\end{equation}
\begin{equation}
= \frac{36}{0.02} \int_{0}^{0.02} (\sin^2 314t) dt = \frac{18}{0.02} \int_{0}^{0.02} (2\sin^2 314t) dt
\end{equation}
\begin{equation}
= 900 \int_{0}^{0.02} [1 - \cos (2 \times 314t)] dt = 900 \left[ t - \frac{\sin (628t)}{628} \right]_{0}^{0.02}
\end{equation}
\begin{equation}
= 900 \left[ 0.02 - 0 - \frac{\sin (628 \times 0.02)}{628} + \frac{\sin 0}{628} \right] = 900 \left[ 0.02 - \frac{\sin (12.56)}{628} + 0 \right]
\end{equation}
\begin{equation}
= 900 \left[ 0.02 - \frac{\sin (4 \times 3.14)}{628} \right] = 900 \left[ 0.02 - \frac{\sin 4\pi}{628} \right]; [\sin 4\pi = 0]
\end{equation}
\begin{equation}
= 900 [0.02 - 0] = 18 \text{ V}^2
\end{equation}

